import{_ as r,o,c as a,a2 as l}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"14.1 实操考核概述与评分标准","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-1-shi-cao-kao-he-gai-shu-yu-ping-fen-biao-zhun.md","filePath":"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-1-shi-cao-kao-he-gai-shu-yu-ping-fen-biao-zhun.md","lastUpdated":1795661954000}'),n={name:"electrician/low-voltage-electrician/14-chapter-14-shi-cao-kao-he-yu-ying-shi-ji-qiao/14-1-shi-cao-kao-he-gai-shu-yu-ping-fen-biao-zhun.md"};function i(s,t,d,e,g,h){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="_14-1-实操考核概述与评分标准" tabindex="-1">14.1 实操考核概述与评分标准 <a class="header-anchor" href="#_14-1-实操考核概述与评分标准" aria-label="Permalink to &quot;14.1 实操考核概述与评分标准&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>低压电工考证分<strong>理论</strong>和<strong>实操</strong>两部分。这一节以<strong>重庆地区 2026 年 10 月 9 日起执行的最新实操考试标准</strong>为主线,讲清考什么、怎么评分、多少分合格,并附上旧标准对比,帮你避免照着过时资料备考。</p><h2 id="一、实操考核考什么" tabindex="-1">一、实操考核考什么 <a class="header-anchor" href="#一、实操考核考什么" aria-label="Permalink to &quot;一、实操考核考什么&quot;">​</a></h2><p>低压电工实操考核围绕“安全第一”展开。按 2025 年版《低压电工作业人员安全技术培训大纲和考核标准》,实操分为 <strong>4 个科目</strong>:</p><table tabindex="0"><thead><tr><th>科目</th><th>考核内容</th></tr></thead><tbody><tr><td><strong>科目一 安全用具使用</strong></td><td>电工仪器仪表的安全使用;电力安全工器具的辨识与使用</td></tr><tr><td><strong>科目二 作业现场安全隐患排除</strong></td><td>作业现场安全风险、安全隐患的判断和排除</td></tr><tr><td><strong>科目三 安全操作技术</strong></td><td>电动机单向/正反转接线、电能表带照明灯接线、导线连接、低压配电柜操作与维护、临时用电系统设置等</td></tr><tr><td><strong>科目四 作业现场应急处置</strong></td><td>触电现场处置、单人徒手心肺复苏、灭火器的选择与使用</td></tr></tbody></table><blockquote><p>💡 核心考核理念不变:<strong>“安全操作永远比完成接线更重要”</strong>。即使线路接得快,只要触发安全否决项,一样判不合格。</p></blockquote><h2 id="二、重庆最新考试标准-2026-年-10-月-9-日起" tabindex="-1">二、重庆最新考试标准(2026 年 10 月 9 日起) <a class="header-anchor" href="#二、重庆最新考试标准-2026-年-10-月-9-日起" aria-label="Permalink to &quot;二、重庆最新考试标准(2026 年 10 月 9 日起)&quot;">​</a></h2><h3 id="_1-政策依据" tabindex="-1">1. 政策依据 <a class="header-anchor" href="#_1-政策依据" aria-label="Permalink to &quot;1. 政策依据&quot;">​</a></h3><ul><li><strong>应急管理部令第 19 号</strong>《特种作业人员安全技术培训考核管理规定》,2025 年 12 月 17 日公布,<strong>2026 年 6 月 1 日起施行</strong>;</li><li><strong>《低压电工作业人员安全技术培训大纲和考核标准》(2025 年版)</strong>,应急管理部 2025 年 7 月印发;</li><li><strong>全国统一新版实操考试题库</strong>,自 <strong>2026 年 10 月 9 日</strong>起启用,旧题库同步停用;</li><li><strong>重庆市应急管理局《关于启用低压电工等特种作业操作项目实操考试新题库的提示函》(渝应急函〔2026〕398 号)</strong>。</li></ul><h3 id="_2-四个科目与分值权重" tabindex="-1">2. 四个科目与分值权重 <a class="header-anchor" href="#_2-四个科目与分值权重" aria-label="Permalink to &quot;2. 四个科目与分值权重&quot;">​</a></h3><p>新标准每个科目<strong>随机抽取 1 道题</strong>,四科权重合计 100%:</p><table tabindex="0"><thead><tr><th>科目</th><th>题量</th><th>分值权重</th><th>单题参考时长</th></tr></thead><tbody><tr><td>科目一 安全用具使用</td><td>4 题</td><td><strong>20%</strong></td><td>约 30 分钟</td></tr><tr><td>科目二 作业现场安全隐患排除</td><td>1 题</td><td><strong>20%</strong></td><td>约 10 分钟</td></tr><tr><td>科目三 安全操作技术</td><td>7 题</td><td><strong>40%</strong></td><td>30~50 分钟</td></tr><tr><td>科目四 作业现场应急处置</td><td>6 题</td><td><strong>20%</strong></td><td>5~10 分钟</td></tr></tbody></table><ul><li>2026 年版题库共 <strong>18 道题</strong>(4 + 1 + 7 + 6),具体以市考试中心下发的题库为准;</li><li>最终实操成绩 = 科目一得分×20% + 科目二得分×20% + 科目三得分×40% + 科目四得分×20%;</li><li><strong>科目三分值最高(40%)</strong>,是重点科目,也是拉开差距的关键。</li></ul><h3 id="_3-合格标准-重点" tabindex="-1">3. 合格标准(重点) <a class="header-anchor" href="#_3-合格标准-重点" aria-label="Permalink to &quot;3. 合格标准(重点)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>条件</th><th>要求</th></tr></thead><tbody><tr><td>总分</td><td><strong>80 分及以上</strong></td></tr><tr><td>否决项</td><td><strong>必须全部通过</strong>;否决项未通过,实操直接判不合格</td></tr><tr><td>理论</td><td>理论考试合格后,才能参加实操考试</td></tr><tr><td>发证</td><td>理论、实操<strong>两科均合格</strong>,方可取得特种作业操作证</td></tr></tbody></table><blockquote><p>⚠️ <strong>两个常见误区</strong>:</p><ol><li>不是“每科都要 80 分”。官方考核标准的表述是<strong>总分 80 分 + 否决项通过</strong>;部分培训资料称“每科 80 分”,两者口径不同,以考点执行的官方标准为准。</li><li>不是“总分够了就行”。<strong>否决项一票否决</strong>,总分再高也没用。</li></ol></blockquote><h3 id="_4-考试机会与完成期限" tabindex="-1">4. 考试机会与完成期限 <a class="header-anchor" href="#_4-考试机会与完成期限" aria-label="Permalink to &quot;4. 考试机会与完成期限&quot;">​</a></h3><ul><li>实操考试<strong>最多 5 次</strong>;</li><li>每次不合格,可按规定<strong>免费补考</strong>;</li><li>5 次仍不合格的,须<strong>重新参加理论考试</strong>;</li><li>自考试申请通过之日起,<strong>3 年内</strong>完成全部考试;</li><li>考试成绩由考核发证机关在考试结束后 <strong>10 个工作日内</strong>公布。</li></ul><h3 id="_5-重庆落地与过渡安排-渝应急函〔2026〕398-号" tabindex="-1">5. 重庆落地与过渡安排(渝应急函〔2026〕398 号) <a class="header-anchor" href="#_5-重庆落地与过渡安排-渝应急函〔2026〕398-号" aria-label="Permalink to &quot;5. 重庆落地与过渡安排(渝应急函〔2026〕398 号)&quot;">​</a></h3><p>涉及 5 个工种:低压电工、高压电工、熔化焊接与热切割、登高架设、高处安装维护拆除。</p><table tabindex="0"><thead><tr><th>时间节点</th><th>安排</th></tr></thead><tbody><tr><td>2026-09-01 00:00 起</td><td>上述 5 个工种<strong>暂停新报名、新开班</strong>,待实训设备升级验收后恢复</td></tr><tr><td>2026-09-10 前</td><td>已在培学员完成全部培训,确保能报名考试</td></tr><tr><td>2026-09-30 前</td><td>已培训考生完成<strong>旧题库</strong>实操考试</td></tr><tr><td>2026-10-09 起</td><td>统一启用<strong>全国新版题库</strong>,旧题库停用;未考、补考均按新题库</td></tr><tr><td>过渡期间</td><td>考点增加工作日、周末场次,优先安排积压考生</td></tr></tbody></table><p>重庆的特别要求:</p><ul><li>培训机构须先升级实操设备,经属地应急管理局验收合格,<strong>“合格一家、恢复一家”</strong>;</li><li>新题库资料由<strong>市考试中心</strong>统一发放,未经授权不得上网传播;</li><li>严禁“包过”“最后窗口期”等虚假宣传、哄抬价格、缩减培训学时。</li></ul><blockquote><p>📌 以上过渡安排以重庆市应急管理局、市考试中心和考点发布的最新通知为准;政策原文可在应急管理部官网、重庆市应急管理局官网核对。</p></blockquote><h2 id="三、新旧标准对比" tabindex="-1">三、新旧标准对比 <a class="header-anchor" href="#三、新旧标准对比" aria-label="Permalink to &quot;三、新旧标准对比&quot;">​</a></h2><h3 id="_1-一张表看懂差异" tabindex="-1">1. 一张表看懂差异 <a class="header-anchor" href="#_1-一张表看懂差异" aria-label="Permalink to &quot;1. 一张表看懂差异&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>旧标准(2026-10-09 前)</th><th>新标准(2026-10-09 起)</th></tr></thead><tbody><tr><td>主要依据</td><td>旧版实操题库、旧考核标准</td><td>部令第 19 号 + 2025 年版大纲/考核标准 + 2026 年版全国题库</td></tr><tr><td>科目顺序</td><td>一 安全用具使用;二 安全操作技术;三 安全隐患排除;四 现场应急处置</td><td>一 安全用具使用;二 <strong>作业现场安全隐患排除</strong>;三 <strong>安全操作技术</strong>;四 作业现场应急处置</td></tr><tr><td>题库题量</td><td>39 题(以 2024 版旧标准为例:K1 14、K2 20、K3 4、K4 1)</td><td>18 题(K1 4、K2 1、K3 7、K4 6)</td></tr><tr><td>分值权重</td><td>按旧题库评分表折算</td><td><strong>20% / 20% / 40% / 20%</strong></td></tr><tr><td>合格线</td><td>总分 80 分(2011 版曾为 60 分)</td><td>总分 80 分 + <strong>否决项通过</strong></td></tr><tr><td>否决项后果</td><td>一般本题计 0 分</td><td>否决项未通过,<strong>实操不合格</strong></td></tr><tr><td>补考规则</td><td>不合格允许补考 1 次</td><td>实操最多 5 次,每次可免费补考;5 次仍不合格重考理论</td></tr><tr><td>完成期限</td><td>旧规未统一</td><td><strong>3 年内</strong>完成</td></tr><tr><td>考试形式</td><td>实物操作,部分考点仿真</td><td>真人实物、贴近现场;考试全过程<strong>录音录像</strong></td></tr><tr><td>单题时长</td><td>约 7~20 分钟</td><td>约 5~50 分钟,全程平均约 1.5 小时</td></tr></tbody></table><h3 id="_2-旧标准为什么容易-踩坑" tabindex="-1">2. 旧标准为什么容易“踩坑” <a class="header-anchor" href="#_2-旧标准为什么容易-踩坑" aria-label="Permalink to &quot;2. 旧标准为什么容易“踩坑”&quot;">​</a></h3><ul><li><strong>科目顺序不同</strong>:旧标准科目二是安全操作技术、科目三是安全隐患排除;新标准把隐患排除提前到科目二,操作技术放到科目三。照着旧题顺序背,容易答错科目。</li><li><strong>题量大幅压缩</strong>:旧标准 39 题,新标准 18 题,单题更综合、更贴近现场,靠“背步骤”通过的难度上升。</li><li><strong>否决项更严</strong>:旧标准否决项通常只把本题计 0 分;新标准明确否决项未通过则实操不合格,安全防护、验电等动作必须一步到位。</li><li><strong>机会变多但期限更紧</strong>:新标准给到 5 次机会,但必须在 3 年内完成,且理论合格后才能考实操。</li></ul><h3 id="_3-合格线演变-了解即可" tabindex="-1">3. 合格线演变(了解即可) <a class="header-anchor" href="#_3-合格线演变-了解即可" aria-label="Permalink to &quot;3. 合格线演变(了解即可)&quot;">​</a></h3><ul><li>2011 年版大纲:理论、实操均百分制,<strong>60 分合格</strong>,不合格可补考 1 次;</li><li>2013 年《安全生产资格考试与证书管理暂行办法》(安监总培训〔2013〕104 号)后:统一提高到 <strong>80 分合格</strong>;</li><li>2026 年 10 月 9 日起:仍为 <strong>80 分</strong>,但增加<strong>科目权重</strong>和<strong>否决项一票否决</strong>。</li></ul><h2 id="四、重庆考场执行要求" tabindex="-1">四、重庆考场执行要求 <a class="header-anchor" href="#四、重庆考场执行要求" aria-label="Permalink to &quot;四、重庆考场执行要求&quot;">​</a></h2><p>重庆对实操考场有明确的硬件和布线要求(《重庆市安全生产考试点管理暂行规定》,渝应急发〔2021〕100 号),这些细节也会影响评分:</p><ul><li><strong>安全电压</strong>:电工实操设备供电电压应降到人体能承受的 <strong>36V</strong> 范围内;</li><li><strong>配电系统</strong>:采用 <strong>TN-S(三相五线)</strong>,做到“三级配电、两级保护”;PE 与 N 分开,保护接地电阻<strong>不大于 4Ω</strong>;</li><li><strong>接线方式</strong>:必须<strong>传统接线</strong>,不得插孔接线;端子排<strong>严禁做任何标注、标识</strong>;</li><li><strong>布线规范</strong>:采用线槽走线,横平竖直、成排成束,不得“蜘蛛网”式布线;</li><li><strong>安装底板</strong>:电器元件不得装在木板或金属网孔板上,必须使用<strong>环氧树脂绝缘板</strong>;</li><li><strong>工位要求</strong>:工位间隔设置,仪器、工具配备齐全,<strong>不得考生相互共用</strong>;</li><li><strong>监控留存</strong>:实操考场监控全覆盖,录像资料保存<strong>不少于 3 年</strong>。</li></ul><blockquote><p>💡 这些是考场建设标准,不是每一场考试都会逐条检查,但反映了重庆考官看重“规范、安全、可追溯”。练习时就按这个标准做,上考场不会吃亏。</p></blockquote><h2 id="五、实操考核规则说明" tabindex="-1">五、实操考核规则说明 <a class="header-anchor" href="#五、实操考核规则说明" aria-label="Permalink to &quot;五、实操考核规则说明&quot;">​</a></h2><h3 id="_1-考前规则" tabindex="-1">1. 考前规则 <a class="header-anchor" href="#_1-考前规则" aria-label="Permalink to &quot;1. 考前规则&quot;">​</a></h3><ul><li><strong>身份核验</strong>:凭本人身份证、准考证入场,做到人证一致;替考按严重违纪处理;</li><li><strong>按时到场</strong>:按规定时间到达候考区,迟到可能被取消当场考试资格;</li><li><strong>物品管理</strong>:手机、智能手表、复习资料等一般不得带入考场,按要求集中存放;</li><li><strong>抽签定题</strong>:现场抽签确定科目和顺序,不得自行挑题、换题或与他人调换。</li></ul><h3 id="_2-考中规则" tabindex="-1">2. 考中规则 <a class="header-anchor" href="#_2-考中规则" aria-label="Permalink to &quot;2. 考中规则&quot;">​</a></h3><ul><li><strong>听令操作</strong>:按考评员口令开始和停止,未宣布开始不得提前动手;</li><li><strong>安全优先</strong>:按规定穿戴劳动防护用品,坚持先断电、再验电、后操作;</li><li><strong>边做边口述</strong>:多数考场要求口述操作步骤,只做不说会被扣分;</li><li><strong>限时完成</strong>:每个科目有规定时限,超时按规则扣分,严重超时终止该科目;</li><li><strong>独立完成</strong>:不得相互交流、旁观他人操作或接受他人提示。</li></ul><h3 id="_3-评分规则" tabindex="-1">3. 评分规则 <a class="header-anchor" href="#_3-评分规则" aria-label="Permalink to &quot;3. 评分规则&quot;">​</a></h3><ul><li><strong>现场评分</strong>:考评员依据评分表逐项打分,普遍采用<strong>扣分制</strong>;</li><li><strong>过程与结果并重</strong>:既看接线、操作结果,也看过程是否规范、安全;</li><li><strong>全程留痕</strong>:按部令第 19 号要求,考试全过程<strong>录音录像</strong>,考评员签字确认;</li><li><strong>异议当场提</strong>:对评分有异议,应当场向考务组提出,事后一般不再受理。</li></ul><h3 id="_4-违纪与否决规则" tabindex="-1">4. 违纪与否决规则 <a class="header-anchor" href="#_4-违纪与否决规则" aria-label="Permalink to &quot;4. 违纪与否决规则&quot;">​</a></h3><table tabindex="0"><thead><tr><th>情形</th><th>处理</th></tr></thead><tbody><tr><td>未验电即操作、带电作业,或违规操作造成短路、设备损坏</td><td>触发否决项,实操判不合格</td></tr><tr><td>不按规定穿戴绝缘手套、绝缘鞋等防护用品</td><td>触发否决项或扣分,情节严重的判不合格</td></tr><tr><td>替考、作弊、携带资料入场</td><td>取消考试成绩,按规定处理</td></tr><tr><td>不服从考评员管理、扰乱考场秩序</td><td>终止考试,情节严重的取消考试资格</td></tr></tbody></table><h2 id="六、实操考核流程-通用模式" tabindex="-1">六、实操考核流程(通用模式) <a class="header-anchor" href="#六、实操考核流程-通用模式" aria-label="Permalink to &quot;六、实操考核流程(通用模式)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>抽题/候场 → 讲解安全要求 → 按科目顺序操作 → 考官检查评分 → 收尾</span></span></code></pre></div><ul><li>操作前认真听清题目要求,确认考试科目和时限;</li><li>操作中<strong>边做边口述</strong>(很多考场要求叙述步骤),条理清晰;</li><li>操作后<strong>主动检查、汇报完成</strong>,做好收尾和送电前检查。</li></ul><h2 id="七、备考建议" tabindex="-1">七、备考建议 <a class="header-anchor" href="#七、备考建议" aria-label="Permalink to &quot;七、备考建议&quot;">​</a></h2><ol><li><strong>按新科目顺序练</strong>:科目一仪表与安全用具 → 科目二隐患排查 → 科目三接线与配电柜、临时用电 → 科目四急救与灭火;</li><li><strong>主攻科目三</strong>:占总分 40%,把电动机单向/正反转、电能表带照明灯、导线连接、低压配电柜、临时用电系统练熟;</li><li><strong>科目二练“看图找隐患”</strong>:柜门未接保护线、缆沟盖板无绝缘垫、多路压接不合理、控制柜上堆杂物等;</li><li><strong>科目四练标准动作</strong>:心肺复苏的位置、频率、比例,灭火器的选择与“提、拔、握、压”;</li><li><strong>把否决项练成肌肉记忆</strong>:断电、验电、挂接地线/挂牌、绝缘防护,一步都不能省;</li><li><strong>按单题限时训练</strong>:新标准题量少但单题更综合,超时会直接丢分。</li></ol><h2 id="八、考点提示" tabindex="-1">八、考点提示 <a class="header-anchor" href="#八、考点提示" aria-label="Permalink to &quot;八、考点提示&quot;">​</a></h2><ul><li>✅ 重庆现行标准:2026-10-09 起启用全国新题库(渝应急函〔2026〕398 号)。</li><li>✅ 四科权重 <strong>20% / 20% / 40% / 20%</strong>,科目三最重要。</li><li>✅ 合格:总分 <strong>80 分</strong> + <strong>否决项通过</strong>;理论合格后才能考实操。</li><li>✅ 机会:实操<strong>最多 5 次</strong>,可免费补考,<strong>3 年内</strong>完成。</li><li>✅ 旧标准:科目二、三顺序相反,39 题,补考 1 次。</li><li>⚠️ 易混点:官方口径是“总分 80 + 否决项”,不要轻信“每科都要 80 分”的说法。</li></ul><h2 id="九、本节小结" tabindex="-1">九、本节小结 <a class="header-anchor" href="#九、本节小结" aria-label="Permalink to &quot;九、本节小结&quot;">​</a></h2><ul><li>新标准四科:安全用具使用、隐患排除、安全操作技术、应急处置。</li><li>权重 20/20/40/20,总分 80 合格,否决项一票否决。</li><li>旧标准科目二、三顺序相反,题量 39 题,补考 1 次。</li><li>重庆 2026-10-09 起用新题库,旧题库 9 月 30 日前用完。</li></ul><h2 id="十、自测练习" tabindex="-1">十、自测练习 <a class="header-anchor" href="#十、自测练习" aria-label="Permalink to &quot;十、自测练习&quot;">​</a></h2><ol><li>(判断)实操考核中,安全操作行为比接线速度更重要。( )</li><li>(单选)新标准中分值权重最高的科目是()。 A. 安全用具使用　B. 作业现场安全隐患排除　C. 安全操作技术　D. 作业现场应急处置</li><li>(单选)重庆自 2026 年 10 月 9 日起,低压电工实操使用()。 A. 旧题库　B. 全国新版题库　C. 各考点自命题　D. 理论题库</li><li>(判断)新标准下,只要总分达到 80 分,即使触发安全否决项也能合格。( )</li><li>(多选)新标准实操四科目包括()。 A. 安全用具使用　B. 作业现场安全隐患排除　C. 安全操作技术　D. 作业现场应急处置</li><li>(判断)实操考试最多 5 次,5 次仍不合格需重新参加理论考试。( )</li><li>(判断)理论考试未合格,也可以先参加实操考试。( )</li><li>(单选)新标准四科分值权重是()。 A. 25/25/25/25　B. 20/20/40/20　C. 40/20/20/20　D. 30/30/20/20</li><li>(判断)旧标准中科目二是安全操作技术,新标准把安全隐患排除放到了科目二。( )</li><li>(判断)重庆规定电工实操设备供电电压应降到 36V 安全电压范围内。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。安全第一,安全行为权重最高。</li><li><strong>C</strong>。科目三安全操作技术占 40%。</li><li><strong>B</strong>。2026-10-09 起全国统一启用新版实操题库。</li><li><strong>×</strong>。否决项未通过,总分再高也判不合格。</li><li><strong>ABCD</strong>。四科为安全用具使用、隐患排除、安全操作技术、应急处置。</li><li><strong>√</strong>。实操最多 5 次,5 次仍不合格须重考理论。</li><li><strong>×</strong>。理论合格后才能参加实操。</li><li><strong>B</strong>。20% / 20% / 40% / 20%。</li><li><strong>√</strong>。新标准把隐患排除提前到科目二,操作技术放到科目三。</li><li><strong>√</strong>。重庆要求电工实操设备供电降到 36V 安全电压范围内。</li></ol></details>',57)])])}const b=r(n,[["render",i]]);export{c as __pageData,b as default};
